// Generated from src/registry/sources/control-ui/recipes/collapsible.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const collapsibleKnobs = [
  "--cui-collapsible-trigger-radius",
  "--cui-collapsible-trigger-hover-background",
  "--cui-collapsible-trigger-padding-inline",
  "--cui-collapsible-trigger-padding-block",
  "--cui-collapsible-trigger-font-size",
  "--cui-collapsible-trigger-foreground",
  "--cui-collapsible-trigger-hover-foreground",
] as const;
export type CollapsibleKnobStyle = Partial<Record<(typeof collapsibleKnobs)[number], string>>;

@layer components {
  :where([data-control-family="collapsible"][data-slot="root"]) {
    --cui-collapsible-trigger-radius: var(--radius-control);
    --cui-collapsible-trigger-hover-background: var(--hover-fill);
    --cui-collapsible-trigger-padding-inline: calc(var(--spacing) * 2);
    --cui-collapsible-trigger-padding-block: 0px;
    --cui-collapsible-trigger-foreground: var(--foreground);
    --cui-collapsible-trigger-hover-foreground: var(--foreground);
    --cui-collapsible-trigger-font-size: var(--text-label);
  }

  :where([data-control-family="collapsible"][data-slot="trigger"]) {
    display: flex;
    inline-size: 100%;
    min-block-size: var(--control-h-sm);
    align-items: center;
    gap: calc(var(--spacing) * 2);
    border-radius: var(--cui-collapsible-trigger-radius);
    padding-block: var(--cui-collapsible-trigger-padding-block);
    padding-inline: var(--cui-collapsible-trigger-padding-inline);
    color: var(--cui-collapsible-trigger-foreground);
    font-size: var(--cui-collapsible-trigger-font-size);
    font-weight: var(--font-weight-medium);
    text-align: start;
    transition: background-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="collapsible"][data-slot="trigger"]:focus-visible) {
    background: var(--cui-collapsible-trigger-hover-background);
    color: var(--cui-collapsible-trigger-hover-foreground);
  }

  @media (hover: hover) {
    :where([data-control-family="collapsible"][data-slot="trigger"]:not(:disabled, [data-disabled]):hover) {
      background: var(--cui-collapsible-trigger-hover-background);
      color: var(--cui-collapsible-trigger-hover-foreground);
    }
  }

  :where([data-control-family="collapsible"][data-slot="trigger"]:is(:disabled, [data-disabled])) {
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="collapsible"][data-slot="trigger"] > svg) {
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
    flex-shrink: 0;
    color: var(--muted-foreground);
    transition: rotate var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="collapsible"][data-slot="content"]) {
    height: var(--collapsible-panel-height);
    transition-property: height, opacity;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="collapsible"][data-slot="content"][data-starting-style]),
  :where([data-control-family="collapsible"][data-slot="content"][data-ending-style]) {
    height: 0;
    overflow: clip;
    opacity: 0;
  }

  @supports (transition-behavior: allow-discrete) {
    :where([data-control-family="collapsible"][data-slot="content"]) {
      transition-property: height, opacity, overflow;
      transition-timing-function: var(--ease-standard), var(--ease-standard), step-end;
      transition-behavior: normal, normal, allow-discrete;
    }

    :where([data-control-family="collapsible"][data-slot="content"][data-ending-style]) {
      transition-timing-function: var(--ease-standard), var(--ease-standard), step-start;
    }
  }

  :where([data-control-family="collapsible"][data-slot="trigger"][data-state="open"] > svg) {
    rotate: 90deg;
  }
}

@property --cui-collapsible-trigger-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

